package local.tvmorph.pagecheck;
import android.app.*;
import android.content.*;
import android.os.*;
import android.webkit.WebView;
import java.lang.reflect.Field;
import java.util.concurrent.*;
/** Runs against the installed signed launcher without changing user settings. */
public class LoadingPresentationInstrumentation extends Instrumentation {
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 private WebView web(Activity owner,String field)throws Exception {Field f=owner.getClass().getDeclaredField(field);f.setAccessible(true);return (WebView)f.get(owner);}
 private String eval(WebView browser,String expression)throws Exception {CountDownLatch done=new CountDownLatch(1);String[] answer={null};runOnMainSync(()->browser.evaluateJavascript(expression,v->{answer[0]=v;done.countDown();}));if(!done.await(5,TimeUnit.SECONDS))throw new AssertionError("Javascript timed out");return answer[0];}
 private void check(WebView browser,String expression)throws Exception {for(int i=0;i<60;i++){if("true".equals(eval(browser,expression)))return;Thread.sleep(100);}throw new AssertionError(expression+" returned "+eval(browser,expression));}
 private Activity open(String name){return startActivitySync(new Intent().setClassName("local.tvmorph.tv","local.tvmorph.tv."+name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 private void waitClosed(Activity owner)throws Exception {for(int i=0;i<40&&!owner.isFinishing();i++)Thread.sleep(50);if(!owner.isFinishing())throw new AssertionError("Back did not close "+owner.getClass().getSimpleName());}
 private Activity launchBridge(Activity home,WebView hw)throws Exception {ActivityMonitor monitor=addMonitor("local.tvmorph.tv.BridgeReceiverActivity",null,false);eval(hw,"ClearTV.Catalog.launch(ClearTV.Catalog.get('local.tvmorph.tv.bridge'));true");Activity bridge=waitForMonitorWithTimeout(monitor,5000);removeMonitor(monitor);if(bridge==null)throw new AssertionError("Bridge did not open");check(web(bridge,"browser"),"!!window.MorphReceiverBack&&!!document.getElementById('bridge-back')");return bridge;}
 private void phoneBack(Activity home)throws Exception {Field token=home.getClass().getDeclaredField("token");token.setAccessible(true);java.util.Map<String,String> headers=new java.util.HashMap<>();headers.put("x-tv-morph-token",String.valueOf(token.get(home)));java.lang.reflect.Method handle=home.getClass().getDeclaredMethod("handle",String.class,String.class,java.util.Map.class,byte[].class);handle.setAccessible(true);Object response=handle.invoke(home,"POST","/remote/key",headers,"{\"key\":\"RETURN\"}".getBytes("UTF-8"));Field code=response.getClass().getDeclaredField("code");code.setAccessible(true);if(code.getInt(response)!=200)throw new AssertionError("Remote route failed");}
 @Override public void onStart(){Bundle result=new Bundle();try{
 Activity home=open("TvActivity");WebView hw=web(home,"web");check(hw,"!!window.ReferencePreview");Field liveCoverField=home.getClass().getDeclaredField("startupCover");liveCoverField.setAccessible(true);android.view.View liveCover=(android.view.View)liveCoverField.get(home);for(int wait=0;wait<80&&liveCover.getVisibility()!=android.view.View.GONE;wait++)Thread.sleep(100);if(liveCover.getVisibility()!=android.view.View.GONE)throw new AssertionError("Live cover did not dismiss");check(hw,"!document.getElementById('morph-brand-loader')&&!document.documentElement.classList.contains('theme-starting')&&!!window.ReferencePreview");Field liveLogoField=liveCover.getClass().getDeclaredField("logo");liveLogoField.setAccessible(true);if(liveLogoField.get(liveCover)!=null||liveCover.getBackground()!=null)throw new AssertionError("Hidden startup cover retains bitmap artwork");result.putString("startupMemory","PASS hidden cover releases logo and background references");Class<?> type=getTargetContext().getClassLoader().loadClass("local.tvmorph.tv.StartupCover");java.lang.reflect.Constructor<?> constructor=type.getDeclaredConstructor(android.content.Context.class);constructor.setAccessible(true);android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(1920,1080,android.graphics.Bitmap.Config.ARGB_8888);
 runOnMainSync(()->{try{android.view.View cover=(android.view.View)constructor.newInstance(home);cover.measure(android.view.View.MeasureSpec.makeMeasureSpec(1920,android.view.View.MeasureSpec.EXACTLY),android.view.View.MeasureSpec.makeMeasureSpec(1080,android.view.View.MeasureSpec.EXACTLY));cover.layout(0,0,1920,1080);cover.draw(new android.graphics.Canvas(bitmap));Field logoField=type.getDeclaredField("logo");logoField.setAccessible(true);android.graphics.Bitmap logo=(android.graphics.Bitmap)logoField.get(cover);if(logo==null||logo.getWidth()!=1024)throw new AssertionError("Loading must use full-size current M symbol");}catch(Exception e){throw new RuntimeException(e);}});
 try(java.io.FileOutputStream file=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),"launcher-loading-preview.png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,file);}bitmap.recycle();result.putString("result","PASS native startup: current full-size M symbol, gold color treatment, shared background and revised layout rendered");finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("error",android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
}
